DO $$ declare m_id bigint;q_id bigint;qu_id bigint; begin
select m.id into m_id from public.modules m join public.courses c on c.id=m.course_id where c.slug='documentacao-imobiliaria' and m.position=1;
select id into q_id from public.quizzes where module_id=m_id and title='Teste · Documentação 1 — Documentos Base — aprender a cruzar informação' limit 1;
if q_id is null then insert into public.quizzes(module_id,title,pass_percentage) values(m_id,'Teste · Documentação 1 — Documentos Base — aprender a cruzar informação',80) returning id into q_id; end if;
if not exists(select 1 from public.questions where quiz_id=q_id) then
insert into public.questions(quiz_id,question,explanation,position) values(q_id,'Um único documento prova sozinho toda a situação jurídica, fiscal e urbanística do imóvel?','É necessário cruzar fontes.',1) returning id into qu_id;
insert into public.answers(question_id,answer,is_correct,position) values(qu_id,'Sim',false,1),(qu_id,'Não',true,2);
insert into public.questions(quiz_id,question,explanation,position) values(q_id,'A caderneta predial tem natureza essencialmente fiscal?','A matriz não substitui registo ou urbanismo.',2) returning id into qu_id;
insert into public.answers(question_id,answer,is_correct,position) values(qu_id,'Sim',true,1),(qu_id,'Não',false,2);
insert into public.questions(quiz_id,question,explanation,position) values(q_id,'Divergências relevantes devem ser comunicadas ao interessado?','A mediação exige exatidão e clareza.',3) returning id into qu_id;
insert into public.answers(question_id,answer,is_correct,position) values(qu_id,'Sim',true,1),(qu_id,'Não',false,2);
insert into public.questions(quiz_id,question,explanation,position) values(q_id,'A eliminação da exibição da autorização de utilização na transmissão significa que a situação urbanística deixou de interessar?','Simplificação formal não equivale a legalização.',4) returning id into qu_id;
insert into public.answers(question_id,answer,is_correct,position) values(qu_id,'Sim',false,1),(qu_id,'Não',true,2);
insert into public.questions(quiz_id,question,explanation,position) values(q_id,'A checklist deve variar com o tipo de imóvel e a operação?','As verificações variam.',5) returning id into qu_id;
insert into public.answers(question_id,answer,is_correct,position) values(qu_id,'Sim',true,1),(qu_id,'Não',false,2);
end if; end $$;
