select m.id,'Dossier antes do CPCV','d11-1-dossier-antes-do-cpcv','{"intro": "Aprenda a tratar dossier antes do cpcv como parte de uma due diligence documental: o objetivo é perceber o que o documento prova, o que não prova, como o cruzar com outras fontes e que divergências exigem validação adicional.", "sections": [{"title": "O que verificar", "body": "Aprenda a tratar dossier antes do cpcv como parte de uma due diligence documental: o objetivo é perceber o que o documento prova, o que não prova, como o cruzar com outras fontes e que divergências exigem validação adicional."}, {"title": "Como cruzar", "body": "Compare registo, matriz, urbanismo, propriedade horizontal, energia e realidade física conforme o tipo de imóvel e a operação."}, {"title": "Na comercialização", "body": "Comunique apenas factos suportados e identifique informação pendente de confirmação."}], "takeaway": "Documento obtido não significa due diligence concluída: confirme conteúdo, atualidade, correspondência e efeito no negócio."}'::jsonb,10,true,date '2026-08-18','https://justica.gov.pt/Servicos/Balcao-Casa-Pronta','published',1
